#include <stdbool.h>
#include <stdint.h>

#define TEMP_SENSOR_COUNT 4u
#define CHARGE_OT_TRIP_C 55
#define CHARGE_OT_CLEAR_C 50
#define CHARGE_OT_CONFIRM_SAMPLES 2u

typedef struct {
    int16_t temp_c[TEMP_SENSOR_COUNT];
    uint8_t charge_ot_samples;
    bool charge_ot_fault;
    bool other_charge_inhibit;
    bool charge_allowed;
} Bms;

static void bms_check_charge_overtemperature(Bms *b)
{
    int16_t max_c = b->temp_c[0];
    for (uint8_t i = 1u; i < TEMP_SENSOR_COUNT; ++i) {
        if (b->temp_c[i] > max_c) {
            max_c = b->temp_c[i];
        }
    }

    if (max_c >= CHARGE_OT_TRIP_C) {
        if (b->charge_ot_samples < CHARGE_OT_CONFIRM_SAMPLES) {
            ++b->charge_ot_samples;
        }
    } else if (max_c <= CHARGE_OT_CLEAR_C) {
        b->charge_ot_samples = 0u;
    }

    if (b->charge_ot_samples >= CHARGE_OT_CONFIRM_SAMPLES) {
        b->charge_ot_fault = true;
        b->charge_allowed = false;
    } else if (max_c <= CHARGE_OT_CLEAR_C && b->charge_ot_samples == 0u) {
        b->charge_ot_fault = false;
        b->charge_allowed = !b->other_charge_inhibit;
    }
}

void bms_100ms_task(Bms *b)
{
    bms_check_charge_overtemperature(b);
}
